        "resposta": "Estar em Cristo, comungando com Ele e permanecendo nEle: \"se alguém está em Cristo, é nova criatura\" (2 Coríntios 5:17); \"Permanecei em mim, e eu permanecerei em vós\" (João 15:4)."
