              "Ellen G. White registrou: \"O Senhor mostrou-me claramente que a imagem da besta formar-se-á antes que termine a graça; pois isso será a grande prova para o povo de Deus, pela qual será decidido seu destino eterno.\" (Mensagens Escolhidas, vol. 2, pág. 81)",
              "O que é a imagem da besta? A imagem é formada quando o poder religioso dirige o governo civil a ponto de a autoridade do Estado ser empregada pela igreja para realizar os seus próprios fins. \"A imagem da besta representa a forma de protestantismo apóstata que se desenvolverá quando as igrejas protestantes buscarem o auxílio do poder civil para imposição de seus dogmas.\" (O Grande Conflito, pág. 443, 445) A imposição da lei dominical será a grande prova final, e ela precede o fim do tempo da graça."
