              "Ellen G. White descreve o momento: \"Vi anjos indo aceleradamente de um lado para o outro no céu. Um anjo, com um tinteiro de escrivão ao lado, voltou da Terra e referiu a Jesus que sua obra estava feita, e os santos estavam numerados e selados. Então vi Jesus, que havia estado a ministrar diante da arca, a qual contém os Dez Mandamentos, lançar o incensário. Levantou as mãos e com grande voz disse: Está feito.\" (Primeiros Escritos, pág. 279) \"Cessa então Jesus de interceder no santuário celestial. Levanta as mãos, e com grande voz diz: Está feito.\" (O Grande Conflito, pág. 613)"
